// Multiplicação de segurança: Garante que os arrays cubram os 365 (ou 366) dias do ano sem falhas
['menstrual', 'folicular', 'ovulatoria', 'lutea'].forEach(fase => {
    let dicas = window.AcervoDicasMulher[fase];
    while (dicas.length < 366) {
        dicas = dicas.concat(dicas);
    }
    window.AcervoDicasMulher[fase] = dicas;
});

let dicasBemEstar = window.AcervoBemEstarMulher;
